contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run performs a withdraw on c of amount `amt` and asserts the general balance-transfer property.
    // This contract is the owner of c because c was deployed with msg.sender = this contract.
    function run(uint amt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);
        // Record balances before the withdraw call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Perform the withdraw and capture whether it reverted.
        bool withdrewReverted;
        c.withdraw(amt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }

        // Read balances after the withdraw attempt
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // Assert the general rule: if withdraw succeeded, c.balance decreased by amt and this.balance increased by amt;
        // if it reverted, neither balance changed.
        assert(
            ( !withdrewReverted && afterC == beforeC - amt && afterThis == beforeThis + amt )
            ||
            ( withdrewReverted && afterC == beforeC && afterThis == beforeThis )
        );
    }

    // Allow receiving ETH when c.withdraw sends funds here
    receive() external payable {}
}

