// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amt) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        bool withdrewReverted;
        try c.withdraw(amt) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        assertTrue(( !withdrewReverted && afterC == beforeC - amt && afterThis == beforeThis + amt )
            ||
            ( withdrewReverted && afterC == beforeC && afterThis == beforeThis ));
    }

    function testFuzz_run(uint256 amt) public {
        _run(amt);
    }

    receive() external payable {}
}
